column3:
}
pool.operations.pop();

// 第三段：根槽 FUA，区域 3 mod 3 = 0 的槽 1（暖机之后第一个事务是 txg 3）。

if fua_is_boundary && is_fua {
    let fua_index = current.pop().expect("刚 push 过");
    if !current.is_empty() {
        segments.push(std::mem::take(&mut current));
    }
    segments.push(vec![fua_index]);
}
